package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector.ebeDivide
 */
public class OpenMapRealVector_ebeDivide_TriageGen5Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testEbeDivideSuccess() {
        // Setup: Create a sparse vector (this)
        OpenMapRealVector v1 = new OpenMapRealVector(5);
        v1.setEntry(0, 10.0);
        v1.setEntry(2, 20.0);
        v1.setEntry(4, 30.0);

        // Setup: Create divisor vector v
        OpenMapRealVector v2 = new OpenMapRealVector(5);
        v2.setEntry(0, 2.0);
        v2.setEntry(1, 5.0);
        v2.setEntry(2, 4.0);
        v2.setEntry(3, 1.0);
        v2.setEntry(4, 10.0);

        // Execute
        OpenMapRealVector result = v1.ebeDivide(v2);

        // Verify dimensions
        Assert.assertEquals("Dimension should match", v1.getDimension(), result.getDimension());

        // Verify specific entries (only indices present in v1 should be processed)
        // index 0: 10.0 / 2.0 = 5.0
        Assert.assertEquals(5.0, result.getEntry(0), EPSILON);
        // index 2: 20.0 / 4.0 = 5.0
        Assert.assertEquals(5.0, result.getEntry(2), EPSILON);
        // index 4: 30.0 / 10.0 = 3.0
        Assert.assertEquals(3.0, result.getEntry(4), EPSILON);

        // Verify that indices not in v1 (like index 1 or 3) remain zero/default in result
        // because the loop iterates over res.entries (which is a copy of v1)
        Assert.assertEquals(0.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(3), EPSILON);
    }

    @Test
    public void testEbeDivideEmptyVector() {
        // Test with an empty (all zeros) OpenMapRealVector
        OpenMapRealVector v1 = new OpenMapRealVector(3);
        OpenMapRealVector v2 = new OpenMapRealVector(new double[]{1.0, 2.0, 3.0});

        OpenMapRealVector result = v1.ebeDivide(v2);

        Assert.assertEquals(3, result.getDimension());
        Assert.assertEquals(0.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(2), EPSILON);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testEbeDivideDimensionMismatch() {
        // v1 has dimension 3
        OpenMapRealVector v1 = new OpenMapRealVector(3);
        v1.setEntry(0, 10.0);

        // v2 has dimension 2
        RealVector v2 = new ArrayRealVector(new double[]{1.0, 2.0});

        // This should trigger checkVectorDimensions and throw DimensionMismatchException
        v1.ebeDivide(v2);
    }

    @Test
    public void testEbeDivideWithDivisionByZero() {
        // Test behavior when divisor contains zero at a non-zero index of the numerator
        OpenMapRealVector v1 = new OpenMapRealVector(2);
        v1.setEntry(0, 10.0);
        v1.setEntry(1, 5.0);

        OpenMapRealVector v2 = new OpenMapRealVector(2);
        v2.setEntry(0, 2.0);
        v2.setEntry(1, 0.0); // Division by zero

        OpenMapRealVector result = v1.ebeDivide(v2);

        Assert.assertEquals(5.0, result.getEntry(0), EPSILON);
        Assert.assertTrue("Result at index 1 should be Infinity", Double.isInfinite(result.getEntry(1)));
    }

    @Test
    public void testEbeDivideWithNaN() {
        OpenMapRealVector v1 = new OpenMapRealVector(1);
        v1.setEntry(0, 10.0);

        OpenMapRealVector v2 = new OpenMapRealVector(1);
        v2.setEntry(0, Double.NaN);

        OpenMapRealVector result = v1.ebeDivide(v2);

        Assert.assertTrue("Result should be NaN", Double.isNaN(result.getEntry(0)));
    }
}
